#!/bin/sh
# layer-3 phase 3 ACCEPTANCE lane -- dart -- generated by
# Research/kind_fuzz_clustering/l3_lanes.py .  Do not hand-edit.
# Route: value matrix, route A, shard 0/1.  Probes: 113 (full ordered pairs x operation menu).
set -u
export HOME=/work
export GO111MODULE=off
export GOFLAGS=-mod=mod
export GOCACHE=/work/.gocache
export GOPATH=/work/.gopath
export PATH=/persist/dart-sdk/bin:$PATH
ncurses_fix() {
  if [ -f /usr/lib/x86_64-linux-gnu/libncursesw.so.6.6 ]; then
    ln -sf /usr/lib/x86_64-linux-gnu/libncursesw.so.6.6 \
       /usr/lib/x86_64-linux-gnu/libncurses.so.6 2>/dev/null
    ldconfig 2>/dev/null
  fi
}
ncurses_fix
ROOT=/work/ld_dart_00
rm -rf "$ROOT"; mkdir -p "$ROOT"
echo "=== layer-3 acceptance -- dart -- route value matrix, route A, shard 0/1 -- 113 probes ==="
